#!/usr/bin/env python3
"""Generate the singular drop-start gate from the pinned C++ probe."""
import importlib.util
import pathlib
import subprocess
import sys

HERE = pathlib.Path(__file__).resolve().parent
spec = importlib.util.spec_from_file_location('drops', HERE.parent / 'drop-curve/generate.py')
drops = importlib.util.module_from_spec(spec)
spec.loader.exec_module(drops)
CASES = []
for axis, patch in ((1, drops.POLE), (0, drops.POLE_V)):
    for fixed in (0.0, 0.25, 0.5, 0.75, 1.0):
        curve = patch.iso(axis, fixed)
        for t in (0.0, 1e-8, 0.2, 1.0):
            uv = (t, fixed) if axis == 1 else (fixed, t)
            kind = 'singular' if t == 0 else 'near-singular' if t == 1e-8 else 'regular'
            CASES.append(('start', kind, f'{patch.text} {drops.v(0, 0, 1, 1)} {curve} {drops.v(0, 1, *uv, t)}'))
# A collapsed curve has no tangent and must fail, including at the pole.
CASES.append(('start', 'singular', f'{drops.POLE.text} {drops.v(0, 0, 1, 1)} {drops.POLE.iso(0, 0)} {drops.v(0, 1, 0, 0.5, 0)}'))


def main():
    raw = pathlib.Path(sys.argv[2])
    raw.mkdir(parents=True, exist_ok=True)
    lines = []
    for index, (op, kind, inputs) in enumerate(CASES):
        request = f'{op} {inputs}\n'
        run = subprocess.run(['prlimit', '--core=0', '--as=1073741824', '--cpu=20', 'timeout', '40', sys.argv[1]],
                             input=request, capture_output=True, text=True)
        (raw / f'{index:04d}.txt').write_text(f'request: {request}exit: {run.returncode}\nstdout: {run.stdout}stderr: {run.stderr}')
        if run.returncode:
            sys.exit(f'case {index}: oracle exit {run.returncode}: {run.stderr}')
        response = run.stdout.split()
        assert response[0] == op
        lines.append(f'{op} {kind} | {inputs} | {" ".join(response[1:])}')
    (HERE / 'cases.txt').write_text('# Generated by generate.py against pinned SMLib; see README.md.\n' + '\n'.join(lines) + '\n')
    print(f'{len(lines)} cases')


if __name__ == '__main__':
    main()
